window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-19d5fb0ae978beb1"]={"versions": [{"id": "FIG-19d5fb0ae978beb1", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Subdiagramm) zur Spezifikation des Algorithmus „Calculate CRC over Data ID and Data“ im Rahmen des AUTOSAR E2E-Profils 1 (<code>E2E_P01Protect()</code> und <code>E2E_P01Check()</code>). Das Diagramm modelliert den internen Kontrollfluss der E2E-Bibliothek zur sukzessiven Berechnung einer 8-Bit-CRC über konfigurierte Identifikatoren (<code>DataID</code>) und Nutzdaten-Bytebereiche unter Einbindung der AUTOSAR-Basissoftwarefunktion <code>Crc_CalculateCRC8()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten & Datenstrukturen</strong>:</li>\n<li><code>Config</code>: Konfigurationsstruktur mit den Feldern <code>DataIDMode</code>, <code>DataID</code>, <code>CRCOffset</code> (in Bits) und <code>DataLength</code> (in Bits).</li>\n<li><code>State</code>: Zustandsstruktur mit dem Zählerfeld <code>Counter</code>.</li>\n<li><code>Data</code>: Byte-Array der Nutzdaten.</li>\n<li><code>CRC</code>: Lokale 8-Bit-Prüfsummenvariable.</li>\n<li><strong>Funktionsschnittstelle</strong>:</li>\n<li><code>Crc_CalculateCRC8(Crc_DataPtr, Crc_Length, Crc_StartValue8, Crc_IsFirstCall)</code>: Berechnungsfunktion der CRC-Bibliothek.</li>\n<li><strong>Modi (<code>Config-&gt;DataIDMode</code>)</strong>:</li>\n<li><code>E2E_P01_DATAID_BOTH</code></li>\n<li><code>E2E_P01_DATAID_LOW</code></li>\n<li><code>E2E_P01_DATAID_ALT</code></li>\n<li><code>E2E_P01_DATAID_NIBBLE</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Startknoten</strong>: Eintritt in das Subdiagramm.</li>\n<li><strong>DataID-Verzweigung (<code>switch Config-&gt;DataIDMode</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>case E2E_P01_DATAID_BOTH</code>: Ausführung von <code>CRC = Crc_CalculateCRC8(Config-&gt;DataID, 1, 0xFF, FALSE)</code>, gefolgt von <code>CRC = Crc_CalculateCRC8(Config-&gt;DataID &gt;&gt; 8, 1, CRC, FALSE)</code> (CRC über 2 Bytes).</li>\n<li><code>case E2E_P01_DATAID_LOW</code>: Ausführung von <code>CRC = Crc_CalculateCRC8(Config-&gt;DataID, 1, 0xFF, FALSE)</code> (CRC nur über das niederwertige Byte).</li>\n<li><code>case E2E_P01_DATAID_ALT</code>: Verzweigung anhand von <code>State-&gt;Counter % 2 == 0</code>. Bei geradem Zählerstand wird <code>CRC = Crc_CalculateCRC8(Config-&gt;DataID, 1, 0xFF, FALSE)</code> ausgeführt; bei ungeradem Zählerstand wird <code>CRC = Crc_CalculateCRC8(Config-&gt;DataID &gt;&gt; 8, 1, 0xFF, FALSE)</code> ausgeführt (alternierende Einbindung).</li>\n<li><code>case E2E_P01_DATAID_NIBBLE</code>: Ausführung von <code>CRC = Crc_CalculateCRC8(Config-&gt;DataID, 1, 0xFF, FALSE)</code>, gefolgt von <code>CRC = Crc_CalculateCRC8(0, 1, CRC, FALSE)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zusammenführung</strong>: Zusammenführung der vier Pfade in einem Merge-Knoten.</li>\n<li><strong>Prüfung Datenbereich vor CRC (<code>Config-&gt;CRCOffset &gt;= 8</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: <code>CRC = Crc_CalculateCRC8(Data, (Config-&gt;CRCOffset / 8), CRC, FALSE)</code> verarbeitet die Bytes vor dem CRC-Feld.</li>\n<li><code>[FALSE]</code>: Umgehung dieser Aktion.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prüfung Datenbereich nach CRC (<code>Config-&gt;CRCOffset / 8 &lt; (Config-&gt;DataLength / 8) - 1</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: <code>CRC = Crc_CalculateCRC8(&amp;Data[Config-&gt;CRCOffset / 8 + 1], (Config-&gt;DataLength / 8 - Config-&gt;CRCOffset / 8 - 1), CRC, FALSE)</code> verarbeitet die Bytes nach dem CRC-Feld bis zum Datenende.</li>\n<li><code>[FALSE]</code>: Umgehung dieser Aktion.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Finalisierung</strong>: Ausführung von <code>CRC = CRC ^ 0xFF</code> zur Negierung der abschließenden XOR-Operation der CRC-Bibliothek.</li>\n<li><strong>Endknoten</strong>: Abschluss der Berechnung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialwert und XOR-Kompensation</strong>: Der erste Aufruf von <code>Crc_CalculateCRC8()</code> erfolgt stets mit dem Startwert <code>0xFF</code>. Da <code>Crc_CalculateCRC8()</code> den übergebenen Startwert intern mit <code>0xFF</code> XOR-verknüpft, resultiert ein effektiver interner Startwert von <code>0x00</code>.</li>\n<li><strong>Verkettung von CRC-Aufrufen</strong>: Folgeaufrufe übergeben den bisher berechneten <code>CRC</code>-Wert als Startwert mit <code>Crc_IsFirstCall = FALSE</code>. Da die vorhergehende Funktionsausführung das Zwischenergebnis vor Rückgabe mit <code>0xFF</code> maskiert und der nachfolgende Aufruf den Startwert erneut mit <code>0xFF</code> XOR-verknüpft, heben sich die Operationen auf (<code>CRC ^ 0xFF ^ 0xFF = CRC</code>).</li>\n<li><strong>Abschluss-XOR</strong>: Nach dem letzten Bibliotheksaufruf invertiert die E2E-Bibliothek das Endergebnis mittels <code>CRC = CRC ^ 0xFF</code>, um das abschließende XOR der Bibliotheksfunktion aufzuheben.</li>\n<li><strong>Offset-Berechnung</strong>: Bit-Offsets und -Längen werden durch ganzzahlige Division durch 8 in Byte-Größen umgerechnet. Byte-Bereiche entfallen, wenn das CRC-Feld am Anfang (<code>CRCOffset &lt; 8</code>) bzw. am Ende der Nutzdaten liegt.</li>\n</ul>"}, {"id": "FIG-0e3ff874a41aa184", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (Subdiagramm) zur Spezifikation des Algorithmus „Calculate CRC over Data ID and Data“ im Rahmen des AUTOSAR E2E-Profils 1 (<code>E2E_P01Protect()</code> und <code>E2E_P01Check()</code>). Das Diagramm modelliert den internen Kontrollfluss der E2E-Bibliothek zur sukzessiven Berechnung einer 8-Bit-CRC über konfigurierte Identifikatoren (<code>DataID</code>) und Nutzdaten-Bytebereiche unter Einbindung der AUTOSAR-Basissoftwarefunktion <code>Crc_CalculateCRC8()</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Entitäten & Datenstrukturen</strong>:</li>\n<li><code>Config</code>: Konfigurationsstruktur mit den Feldern <code>DataIDMode</code>, <code>DataID</code>, <code>CRCOffset</code> (in Bits) und <code>DataLength</code> (in Bits).</li>\n<li><code>State</code>: Zustandsstruktur mit dem Zählerfeld <code>Counter</code>.</li>\n<li><code>Data</code>: Byte-Array der Nutzdaten.</li>\n<li><code>CRC</code>: Lokale 8-Bit-Prüfsummenvariable.</li>\n<li><strong>Funktionsschnittstelle</strong>:</li>\n<li><code>Crc_CalculateCRC8(Crc_DataPtr, Crc_Length, Crc_StartValue8, Crc_IsFirstCall)</code>: Berechnungsfunktion der CRC-Bibliothek.</li>\n<li><strong>Modi (<code>Config-&gt;DataIDMode</code>)</strong>:</li>\n<li><code>E2E_P01_DATAID_BOTH</code></li>\n<li><code>E2E_P01_DATAID_LOW</code></li>\n<li><code>E2E_P01_DATAID_ALT</code></li>\n<li><code>E2E_P01_DATAID_NIBBLE</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Startknoten</strong>: Eintritt in das Subdiagramm.</li>\n<li><strong>DataID-Verzweigung (<code>switch Config-&gt;DataIDMode</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>case E2E_P01_DATAID_BOTH</code>: Ausführung von <code>CRC = Crc_CalculateCRC8(Config-&gt;DataID, 1, 0xFF, FALSE)</code>, gefolgt von <code>CRC = Crc_CalculateCRC8(Config-&gt;DataID &gt;&gt; 8, 1, CRC, FALSE)</code> (CRC über 2 Bytes).</li>\n<li><code>case E2E_P01_DATAID_LOW</code>: Ausführung von <code>CRC = Crc_CalculateCRC8(Config-&gt;DataID, 1, 0xFF, FALSE)</code> (CRC nur über das niederwertige Byte).</li>\n<li><code>case E2E_P01_DATAID_ALT</code>: Verzweigung anhand von <code>State-&gt;Counter % 2 == 0</code>. Bei geradem Zählerstand wird <code>CRC = Crc_CalculateCRC8(Config-&gt;DataID, 1, 0xFF, FALSE)</code> ausgeführt; bei ungeradem Zählerstand wird <code>CRC = Crc_CalculateCRC8(Config-&gt;DataID &gt;&gt; 8, 1, 0xFF, FALSE)</code> ausgeführt (alternierende Einbindung).</li>\n<li><code>case E2E_P01_DATAID_NIBBLE</code>: Ausführung von <code>CRC = Crc_CalculateCRC8(Config-&gt;DataID, 1, 0xFF, FALSE)</code>, gefolgt von <code>CRC = Crc_CalculateCRC8(0, 1, CRC, FALSE)</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zusammenführung</strong>: Zusammenführung der vier Pfade in einem Merge-Knoten.</li>\n<li><strong>Prüfung Datenbereich vor CRC (<code>Config-&gt;CRCOffset &gt;= 8</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: <code>CRC = Crc_CalculateCRC8(Data, (Config-&gt;CRCOffset / 8), CRC, FALSE)</code> verarbeitet die Bytes vor dem CRC-Feld.</li>\n<li><code>[FALSE]</code>: Umgehung dieser Aktion.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Prüfung Datenbereich nach CRC (<code>Config-&gt;CRCOffset / 8 &lt; (Config-&gt;DataLength / 8) - 1</code>)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: <code>CRC = Crc_CalculateCRC8(&amp;Data[Config-&gt;CRCOffset / 8 + 1], (Config-&gt;DataLength / 8 - Config-&gt;CRCOffset / 8 - 1), CRC, FALSE)</code> verarbeitet die Bytes nach dem CRC-Feld bis zum Datenende.</li>\n<li><code>[FALSE]</code>: Umgehung dieser Aktion.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Finalisierung</strong>: Ausführung von <code>CRC = CRC ^ 0xFF</code> zur Negierung der abschließenden XOR-Operation der CRC-Bibliothek.</li>\n<li><strong>Endknoten</strong>: Abschluss der Berechnung.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Initialwert und XOR-Kompensation</strong>: Der erste Aufruf von <code>Crc_CalculateCRC8()</code> erfolgt stets mit dem Startwert <code>0xFF</code>. Da <code>Crc_CalculateCRC8()</code> den übergebenen Startwert intern mit <code>0xFF</code> XOR-verknüpft, resultiert ein effektiver interner Startwert von <code>0x00</code>.</li>\n<li><strong>Verkettung von CRC-Aufrufen</strong>: Folgeaufrufe übergeben den bisher berechneten <code>CRC</code>-Wert als Startwert mit <code>Crc_IsFirstCall = FALSE</code>. Da die vorhergehende Funktionsausführung das Zwischenergebnis vor Rückgabe mit <code>0xFF</code> maskiert und der nachfolgende Aufruf den Startwert erneut mit <code>0xFF</code> XOR-verknüpft, heben sich die Operationen auf (<code>CRC ^ 0xFF ^ 0xFF = CRC</code>).</li>\n<li><strong>Abschluss-XOR</strong>: Nach dem letzten Bibliotheksaufruf invertiert die E2E-Bibliothek das Endergebnis mittels <code>CRC = CRC ^ 0xFF</code>, um das abschließende XOR der Bibliotheksfunktion aufzuheben.</li>\n<li><strong>Offset-Berechnung</strong>: Bit-Offsets und -Längen werden durch ganzzahlige Division durch 8 in Byte-Größen umgerechnet. Byte-Bereiche entfallen, wenn das CRC-Feld am Anfang (<code>CRCOffset &lt; 8</code>) bzw. am Ende der Nutzdaten liegt.</li>\n</ul>"}], "trans": [{"from": "FIG-19d5fb0ae978beb1", "to": "FIG-0e3ff874a41aa184", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
